import{_ as i,o as n,c as u,a2 as k}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Sheria ya Kupinga Ushirikiano","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0047-反垄断法.md","filePath":"sw/0047-反垄断法.md"}'),h={name:"sw/0047-反垄断法.md"};function s(o,a,t,r,e,l){return n(),u("div",null,[...a[0]||(a[0]=[k('<h1 id="sheria-ya-kupinga-ushirikiano" tabindex="-1">Sheria ya Kupinga Ushirikiano <a class="header-anchor" href="#sheria-ya-kupinga-ushirikiano" aria-label="Permalink to &quot;Sheria ya Kupinga Ushirikiano&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>47</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Kupinga Ushirikiano, Kupinga Mauaji, Ushindani wa Soko, Ushirikiano wa Rasilimali, Ushirikiano wa Mazoezi</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-kanuni-za-msingi" tabindex="-1">1. Lengo la Kisheria na Kanuni za Msingi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-kanuni-za-msingi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Kanuni za Msingi&quot;">​</a></h2><p>《Sheria ya Kupinga Ushirikiano》 ni moja ya sheria tano za msingi za ustaarabu wa usawa wa nanga, na lengo lake ni kuzuia na kuzuia tabia za ushirikiano, kulinda ushindani wa haki wa soko, kuboresha ufanisi wa uendeshaji wa uchumi, kudumisha maslahi ya watumiaji na maslahi ya umma wa kijamii, na kukuza ukuzaji wa afya wa uchumi wa usawa. Katika ustaarabu wa usawa wa nanga, kupinga ushirikiano hakielekezi tu ushirikiano katika eneo la uchumi wa jadi, bali pia kwa aina maalum kama vile ushirikiano wa rasilimali za mazoezi, ushirikiano wa maarifa, na ushirikiano wa viwango.</p><p>Sheria hii inaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Ushindani wa Haki</td><td>Kudumisha utaratibu wa soko wa ushindani wa haki, kukataza tabia za ushirikiano zinazoondoa au kupunguza ushindani</td></tr><tr><td>Kanuni ya Kupinga Mauaji</td><td>Kiini cha kupinga ushirikiano ni kupinga mauaji, na kuzuia wanaoshirikiano kwa kutumia nafasi yao ya ushirikiano kunyanyua maslahi ya viumbe wote</td></tr><tr><td>Kanuni ya Ufumbuzi wa Rasilimali</td><td>Rasilimali za mazoezi za umma na maarifa ya msingi lazima zifunguliwe kwa jamii nzima, na ushirikiano wa kibinafsi umekatazwa</td></tr><tr><td>Kanuni ya Usawa wa Ufanisi na Haki</td><td>Kupinga ushirikiano lazima kulinda ufanisi wa ushindani, na pia kuzuia upotevu wa rasilimali unaosababishwa na mgawanyiko wa kuzidi</td></tr><tr><td>Kanuni ya Utekelezaji wa Kati ya Viwango</td><td>Sheria ya kupinga ushirikiano inatumika kwa viwango na masoko yote ndani ya Hengyuanzhou, na ushirikiano wa kati ya viwango pia unatawaliwa</td></tr></tbody></table><h2 id="_2-aina-za-tabia-za-ushirikiano" tabindex="-1">2. Aina za Tabia za Ushirikiano <a class="header-anchor" href="#_2-aina-za-tabia-za-ushirikiano" aria-label="Permalink to &quot;2. Aina za Tabia za Ushirikiano&quot;">​</a></h2><p>Tabia za ushirikiano zinazotawaliwa na sheria hii zinajumuisha aina nne zifuatazo:</p><h3 id="_1-makubaliano-ya-ushirikiano" tabindex="-1">(1) Makubaliano ya Ushirikiano <a class="header-anchor" href="#_1-makubaliano-ya-ushirikiano" aria-label="Permalink to &quot;(1) Makubaliano ya Ushirikiano&quot;">​</a></h3><p>Makubaliano ya ushirikiano yanamaanisha makubaliano, maamuzi, au tabia zingine za ushirikiano zinazoondoa au kupunguza ushindani, na zinajumuisha:</p><ol><li><strong>Makubaliano ya Usawa ya Ushirikiano</strong>: Makubaliano kati ya wafanyabiashara wanaouhusiana na ushindani ya kubadilisha bei, kupunguza uzalishaji, kugawa soko, kupinga pamoja biashara, n.k.</li><li><strong>Makubaliano ya Wima wa Ushirikiano</strong>: Makubaliano kati ya mfanyabiashara na mshirika wa biashara ya kubadilisha bei ya kuuza upya, kupunguza bei ya chini ya kuuza upya, n.k.</li><li><strong>Makubaliano ya Ushirikiano wa Rasilimali za Mazoezi</strong>: Makubaliano kati ya madhehebu ya mazoezi ya kugawa maeneo ya rasilimali za mazoezi, kuunganisha bei ya rasilimali, kupunguza usambazaji wa rasilimali, n.k.</li><li><strong>Makubaliano ya Ushirikiano wa Maarifa</strong>: Makubaliano kati ya taasisi za elimu na madhehebu ya mazoezi ya kuzuia njia za mazoezi, kupunguza uenezi wa maarifa, kuunganisha viwango vya ada za masomo, n.k.</li></ol><h3 id="_2-unyanyafu-wa-nafasi-ya-ushindi-wa-soko" tabindex="-1">(2) Unyanyafu wa Nafasi ya Ushindi wa Soko <a class="header-anchor" href="#_2-unyanyafu-wa-nafasi-ya-ushindi-wa-soko" aria-label="Permalink to &quot;(2) Unyanyafu wa Nafasi ya Ushindi wa Soko&quot;">​</a></h3><p>Nafasi ya ushindi wa soko inamaanisha nafasi ya soko ambayo mfanyabiashara ana uwezo wa kudhibiti bei, idadi, au hali zingine za biashara za bidhaa ndani ya soko inayohusiana, au uwezo wa kuzuia au kuathiri wafanyabiashara wengine kuingia kwenye soko inayohusiana. Tabia za unyanyafu wa nafasi ya ushindi wa soko zinajumuisha:</p><table tabindex="0"><thead><tr><th>Aina ya Tabia</th><th>Maonyesho ya Mahususi</th></tr></thead><tbody><tr><td>Kubadilisha Bei Isiyo Haki</td><td>Kuuza bidhaa kwa bei juu isiyo haki au kununua bidhaa kwa bei chini isiyo haki</td></tr><tr><td>Kubadilisha Bei ya Mauaji</td><td>Bila sababu ya haki, kuuza bidhaa kwa bei chini ya gharama ili kuondoa washindani</td></tr><tr><td>Kukataza Biashara</td><td>Bila sababu ya haki, kukataza kufanya biashara na mshirika wa biashara</td></tr><tr><td>Kupunguza Biashara</td><td>Bila sababu ya haki, kupunguza mshirika wa biashara afanye biashara na yeye tu</td></tr><tr><td>Kuuza Bidhaa Ukiunganisha</td><td>Bila sababu ya haki, kuuza bidhaa ukiunganisha, au kuweka masharti mengine yasiyo haki wakati wa biashara</td></tr><tr><td>Kufanya Ubaguzi</td><td>Bila sababu ya haki, kufanya ubaguzi katika masharti kama vile bei ya biashara kwa washirika wa biashara wenye masharti sawa</td></tr><tr><td>Kuzuia Rasilimali za Mazoezi</td><td>Kutumia nafasi ya ushirikiano wa rasilimali za mazoezi, kukataza kutoa rasilimali zinazohitajika kwa washindani au watumiaji</td></tr><tr><td>Kuzuia Maarifa</td><td>Kutumia nafasi ya ushirikiano wa maarifa, kuzuia njia za msingi za mazoezi, na kulazimisha wanafunzi kulipa ada za juu</td></tr></tbody></table><h3 id="_3-ushirikiano-wa-wafanyabiashara" tabindex="-1">(3) Ushirikiano wa Wafanyabiashara <a class="header-anchor" href="#_3-ushirikiano-wa-wafanyabiashara" aria-label="Permalink to &quot;(3) Ushirikiano wa Wafanyabiashara&quot;">​</a></h3><p>Ushirikiano wa wafanyabiashara unamaanisha hali zifuatazo: kuunganishwa kwa wafanyabiashara; mfanyabiashara kupata udhibiti juu ya wafanyabiashara wengine kupitia kupata hisa au mali; mfanyabiashara kupata udhibiti juu ya wafanyabiashara wengine au uwezo wa kuathiri kwa uamuzi juu ya wafanyabiashara wengine kupitia mikataba, n.k.</p><p>Ushirikiano wa wafanyabiashara uliofikia kiwango cha ripoti lazima uripotiwe kabla kwa taasisi ya utekelezaji wa kupinga ushirikiano, na ambayo haijaripotiwi haiwezi kutekeleza ushirikiano. Wakati taasisi ya utekelezaji wa kupinga ushirikiano inachunguza ushirikiano wa wafanyabiashara, lazima iangalie mambo yafuatayo:</p><ol><li>Sehemu ya soko ya wafanyabiashara wanaoshiriki katika ushirikiano katika soko inayohusiana na uwezo wao wa kudhibiti soko.</li><li>Kiwango cha ushirikiano wa soko la soko inayohusiana.</li><li>Athari ya ushirikiano wa wafanyabiashara kwa uingiaji wa soko na maendeleo ya teknolojia.</li><li>Athari ya ushirikiano wa wafanyabiashara kwa watumiaji na wafanyabiashara wengine wanaohusiana.</li><li>Athari ya ushirikiano wa wafanyabiashara kwa ufumbuzi wa rasilimali za mazoezi na uenezi wa maarifa.</li><li>Athari ya ushirikiano wa wafanyabiashara kwa maendeleo ya uchumi wa kitaifa na maendeleo ya pamoja ya kila kabila.</li></ol><h3 id="_4-unyanyafu-wa-mamlaka-ya-utawala-wa-kuzuia-au-kupunguza-ushindani" tabindex="-1">(4) Unyanyafu wa Mamlaka ya Utawala wa Kuzuia au Kupunguza Ushindani <a class="header-anchor" href="#_4-unyanyafu-wa-mamlaka-ya-utawala-wa-kuzuia-au-kupunguza-ushindani" aria-label="Permalink to &quot;(4) Unyanyafu wa Mamlaka ya Utawala wa Kuzuia au Kupunguza Ushindani&quot;">​</a></h3><p>Mashirika ya utawala na mashirika yaliyoruhusiwa na sheria, kanuni za kufanya kazi ya usimamizi wa maswala ya umma hawafai kunyanyafua mamlaka ya utawala kufanya tabia zifuatazo:</p><ol><li>Kupunguza au kupunguza kwa njia isiyo ya moja kwa moja kitengo au mtu binafsi kufanya biashara, kununua, kutumia bidhaa zilizotolewa na mfanyabiashara aliyeainishwa.</li><li>Kuzuia mtiririko wa huru wa bidhaa kati ya mikoa, kati ya viwango.</li><li>Kuzuia au kupunguza wafanyabiashara wa nje ya mkoa, wafanyabiashara wa nje ya viwango kushiriki katika shughuli za zabuni na zabuni za ndani.</li><li>Kuzuia au kupunguza wafanyabiashara wa nje ya mkoa, wafanyabiashara wa nje ya viwango kuwekeza ndani au kuanzisha tawi.</li><li>Kulazimisha wafanyabiashara kufanya tabia za ushirikiano zilizotajwa katika sheria hii.</li><li>Kuanzisha kanuni zenye maudhui ya kuzuia au kupunguza ushindani.</li></ol><h2 id="_3-kanuni-za-maalum-za-kupinga-ushirikiano-katika-eneo-la-mazoezi" tabindex="-1">3. Kanuni za Maalum za Kupinga Ushirikiano katika Eneo la Mazoezi <a class="header-anchor" href="#_3-kanuni-za-maalum-za-kupinga-ushirikiano-katika-eneo-la-mazoezi" aria-label="Permalink to &quot;3. Kanuni za Maalum za Kupinga Ushirikiano katika Eneo la Mazoezi&quot;">​</a></h2><p>Eneo la mazoezi ni eneo la msingi la kupinga ushirikiano katika ustaarabu wa usawa wa nanga, na sheria hii inaweka kanuni za maalum:</p><ol><li><strong>Wajibu wa Ufumbuzi wa Njia za Msingi</strong>: Njia za msingi za mifumo mia tatu ya mazoezi ya asili ni maarifa ya umma, na hakuna shirika au mtu binafsi anayeruhusiwa kushirikiana, kuzuia, au kufundisha kwa malipo.</li><li><strong>Usambazaji wa Haki wa Rasilimali za Mazoezi</strong>: Rasilimali za mazoezi za umma zinagawanywa kwa haki kupitia mfumo wa mkataba wa uzalishaji wa pamoja, na madhehebu au watu binafsi hawafai kushirikiana rasilimali za mazoezi za ubora wa juu.</li><li><strong>Kukataza Ubaguzi wa Mazoezi</strong>: Madhehebu ya mazoezi hawafai kuweka masharti ya ubaguzi kulingana na kabila, asili, kiwango cha mazoezi, n.k. katika ukodi na kufundisha.</li><li><strong>Wajibu wa Kushiriki Maarifa ya Juu</strong>: Wanaofanya mazoezi waliofikia kiwango cha mtu mwenye nguvu zaidi wa viwango, wana wajibu wa kushiriki na jamii uzoefu wao wa mazoezi na matokeo ya utafiti, chini ya masharti ya kulinda haki ya kimilikiwa ya akili inayofaa.</li><li><strong>Kupinga Ushirikiano wa Maendeleo ya Viwango</strong>: Haki ya maendeleo ya viwango vipya inagawanywa kupitia ushindani wa huru, na madhara ya chache hawafai kushirikiana haki ya maendeleo ya viwango.</li></ol><h2 id="_4-taasisi-ya-utekelezaji-wa-kupinga-ushirikiano" tabindex="-1">4. Taasisi ya Utekelezaji wa Kupinga Ushirikiano <a class="header-anchor" href="#_4-taasisi-ya-utekelezaji-wa-kupinga-ushirikiano" aria-label="Permalink to &quot;4. Taasisi ya Utekelezaji wa Kupinga Ushirikiano&quot;">​</a></h2><p>Serikali inaanzisha taasisi ya utekelezaji wa kupinga ushirikiano, inayohusika na kazi ya utekelezaji wa kupinga ushirikiano, na inafanya wajibu zifuatazo:</p><ol><li>Kuchunguza na kuandaa sera za ushindani zinazohusiana.</li><li>Kupanga uchunguzi, tathmini ya hali ya jumla ya ushindani wa soko, na kuchapisha ripoti za tathmini.</li><li>Kuandaa na kuchapisha mwongozo wa kupinga ushirikiano.</li><li>Kuratibu kazi ya utekelezaji wa utawala wa kupinga ushirikiano.</li><li>Kuchunguza na kuadhibu kesi za makubaliano ya ushirikiano, unyanyafu wa nafasi ya ushindi wa soko, utekelezaji wa ushirikiano wa wafanyabiashara isiyo halali, n.k.</li><li>Kuchunguza na kuadhibu tabia za unyanyafu wa mamlaka ya utawala wa kuzuia au kupunguza ushindani.</li></ol><p>Taasisi ya utekelezaji wa kupinga ushirikiano inatekeleza mamlaka yake kwa uhuru kulingana na sheria, bila kuingiliwa na mashirika ya utawala, mashirika ya kijamii, na watu binafsi.</p><h2 id="_5-wajibu-wa-kisheria" tabindex="-1">5. Wajibu wa Kisheria <a class="header-anchor" href="#_5-wajibu-wa-kisheria" aria-label="Permalink to &quot;5. Wajibu wa Kisheria&quot;">​</a></h2><p>Shughuli zinazovunja masharti ya sheria hii zitabeba wajibu ufuatao kulingana na ukubwa wa makosa:</p><ul><li>Kufanya na kutekeleza makubaliano ya ushirikiano, kuamriwa kusitisha tabia ya kikatili, kunyakuliwa mapato ya kikatili, na kupigwa faini ya 1% hadi 10% ya mapato ya mauzo ya mwaka uliopita.</li><li>Kunyanyafua nafasi ya ushindi wa soko, kuamriwa kusitisha tabia ya kikatili, kunyakuliwa mapato ya kikatili, na kupigwa faini ya 1% hadi 10% ya mapato ya mauzo ya mwaka uliopita.</li><li>Kutekeleza ushirikiano wa wafanyabiashara kwa kikatili, kuamriwa kusitisha utekelezaji wa ushirikiano, kuuza hisa au mali kwa muda, kuhamisha biashara kwa muda, na kupigwa faini ya chini ya yuan 500,000.</li><li>Kunyanyafua mamlaka ya utawala wa kuzuia au kupunguza ushindani, taasisi ya juu inamuamria kurekebisha, na wanajibu wa moja kwa moja na wengine wanaojibu moja kwa moja wanapigwa faini kulingana na sheria.</li><li>Tabia za ushirikiano zinazosababisha uharibifu kwa wengine, wanabeba wajibu wa fidia ya kiraia kulingana na sheria.</li><li>Visa vizito ambavyo vinaunda uhalishi, wanafuatiliwa wajibu wa jinai kulingana na sheria.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Kupinga Ushirikiano》 ni silaha ya kisheria ya anti-predation ya ustaarabu wa usawa wa nanga katika eneo la uchumi na mazoezi. Kupitia kutawaliwa makubaliano ya ushirikiano, unyanyafu wa nafasi ya ushindi wa soko, ushirikiano wa wafanyabiashara na ushirikiano wa utawala, hasa kwa kuweka kanuni za maalum kwa ushirikiano wa rasilimali za mazoezi na ushirikiano wa maarifa, inahakikisha ushindani wa soko na ufumbuzi wa haki wa rasilimali za mazoezi, inazuia ushirikiano kuwa aina mpya ya kunyanyua viumbe wote, na inadumisha mazingira ya kitaaluma ya ushindani wa haki kwa maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>42-消费者保护法 (Sheria ya Kulinda Watumiaji)</li><li>18-修炼资源开放机制 (Mfumo wa Ufumbuzi wa Rasilimali za Mazoezi)</li><li>04-反掠夺主义核心论纲 (Mpango wa Msingi wa Anti-Predation)</li></ul>',35)])])}const y=i(h,[["render",s]]);export{z as __pageData,y as default};
